class SettlementMember { private static int memberCounter = 2000; final String membershipNumber; protected int monthlyFee; private int feesPaid; private String paymentMode; public SettlementMember(int monthlyFee) { if (monthlyFee <= 0) throw new IllegalArgumentException("Invalid monthly fee"); this.monthlyFee = monthlyFee; memberCounter++; membershipNumber = "GYM-" + memberCounter; feesPaid = 0; } public void payFee(int amount) { feesPaid += amount; } public void payFee(int amount, String mode) { paymentMode = mode; payFee(amount); } public int getFeesPaid() { return feesPaid; } public static boolean isValidReferralCode(String code) { if (code == null || code.length() != 4) return false; if (code.charAt(0) != 'G') return false; if (!Character.isDigit(code.charAt(1))) return false; if (!Character.isDigit(code.charAt(2))) return false; if (!Character.isUpperCase(code.charAt(3))) return false; return true; } public static int getMembersEnrolled() { return memberCounter - 2000; } }
class SettlementGroupMember extends SettlementMember { private String className; public SettlementGroupMember(int monthlyFee, String className) { super(monthlyFee); this.className = className; } }
public class MembershipSettlement { public static String processWeeklyCheckIn(SettlementMember[] members) { int processed = 0, nullSkipped = 0, group = 0, individual = 0; for (SettlementMember member : members) { if (member == null) { nullSkipped++; continue; } processed++; if (member instanceof SettlementGroupMember) group++; else individual++; } return processed + " processed | " + nullSkipped + " null skipped | " + group + " group | " + individual + " individual"; } public static void main(String[] args) { SettlementMember m1 = new SettlementMember(1000); System.out.println(m1.membershipNumber); System.out.println(SettlementMember.getMembersEnrolled()); System.out.println(SettlementMember.isValidReferralCode("G45B")); System.out.println(SettlementMember.isValidReferralCode("G4B")); System.out.println(SettlementMember.isValidReferralCode("X45B")); m1.payFee(500); m1.payFee(500, "UPI"); System.out.println(m1.getFeesPaid()); SettlementMember[] members = {new SettlementGroupMember(1500, "Zumba"), null, new SettlementMember(1000)}; System.out.println(processWeeklyCheckIn(members)); } }